<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        span.set_attribute(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;gen_ai.tool.name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, name)</span></span>
